@roblox/globaltype/AnalyticsService.Fire.code_sample:
local AnalyticsService = game:GetService("AnalyticsService")
local Players = game:GetService("Players")

-- 서버 이벤트, 새로운 서버 시작 보고
local serverInfo = {
	Time = os.time(),
	PlaceId = game.PlaceId,
}

AnalyticsService:FireCustomEvent(nil, "ServerStart", serverInfo)

Players.PlayerAdded:Connect(function(player)
	player.Chatted:Connect(function(message)
		local customData = {
			Time = os.time(),
			Message = message,
		}
		AnalyticsService:FireCustomEvent(player, "PlayerChatted", customData)
	end)
end)

local Players = game:GetService("Players")
local TeleportService = game:GetService("TeleportService")
local AnalyticsService = game:GetService("AnalyticsService")

local placeId = game.PlaceId

local player = Players:GetPlayerByUserId(123)

xpcall(function()
	TeleportService:Teleport(placeId, player)
end, function(errorMessage)
	local debugInfo = {
		errorCode = "TeleportFailed",
		stackTrace = debug.traceback(), -- 함수 호출 스택
	}
	AnalyticsService:FireLogEvent(
		player,
		Enum.AnalyticsLogLevel.Error, -- 로그 레벨
		errorMessage, -- 메시지
		debugInfo, -- 선택적
		{
			PlayerId = player.UserId,
			PlaceId = placeId,
		}
	) -- customData 선택적
end)

@roblox/globaltype/AvatarCreationService.code_sample:
local AvatarCreationService = game:GetService("AvatarCreationService")

function generateAvatar(sessionId, previewId)
    local pcallSuccess, result = pcall(function()
        local args = {}
        args.SessionId = sessionId
        args.PreviewId = previewId
        return AvatarCreationService:GenerateAvatarAsync(args)
    end)

    if not pcallSuccess then
        warn("아바타 생성 실패: ", result)
    end

    return result
end

local AvatarCreationService = game:GetService("AvatarCreationService")

function loadAvatar2DPreview(previewId)
    local pcallSuccess, result = pcall(function()
        return AvatarCreationService:LoadAvatar2DPreviewAsync(previewId)
    end)

    if not pcallSuccess then
        warn("미리 로드 실패: ", result)
    end

    return result
end

