@luau/global/setmetatable.code_sample:
local meta = {__metatable = "protected"}
local t = {}
setmetatable(t, meta) -- 이것은 t의 메타테이블을 설정합니다.
-- 이제 메타테이블이 있는 테이블 t가 있습니다. 만약 우리가 그것을 변경하려고 하면...
local ok, err = pcall(setmetatable, t, {})
assert(not ok and err:find("protected")) -- 오류: 보호된 메타테이블을 변경할 수 없습니다.
